/* Candyland Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="candyland-light"] {
  --background: #f8f8f8;
  --foreground: #333333;
  --card: #ffffff;
  --card-foreground: #333333;
  --popover: #ffffff;
  --popover-foreground: #333333;
  --primary: #fec2cc;
  --primary-foreground: #000000;
  --secondary: #87cce8;
  --secondary-foreground: #000000;
  --muted: #dcd8c2;
  --muted-foreground: #6f6f6f;
  --accent: #feff55;
  --accent-foreground: #000000;
  --destructive: #f14444;
  --destructive-foreground: #ffffff;
  --border: #d4d4d4;
  --input: #d4d4d4;
  --ring: #fec2cc;
  --chart-1: #fec2cc;
  --chart-2: #87cce8;
  --chart-3: #feff55;
  --chart-4: #ff97cb;
  --chart-5: #2fcd30;
  --radius: 0.5rem;
  --sidebar: #f8f8f8;
  --sidebar-foreground: #333333;
  --sidebar-primary: #fec2cc;
  --sidebar-primary-foreground: #000000;
  --sidebar-accent: #feff55;
  --sidebar-accent-foreground: #000000;
  --sidebar-border: #d4d4d4;
  --sidebar-ring: #fec2cc;
  --font-sans: Poppins, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: Roboto Mono, monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="candyland-dark"] {
  --background: #1b1d22;
  --foreground: #e4e4e4;
  --card: #2e3437;
  --card-foreground: #e4e4e4;
